mapper.select:
/* 리스트 조회 동적쿼리 */ SELECT s.id, s.name, s.theme, COALESCE(s.bookmark_count, 0) AS bookmark_count,
ROUND(CAST( ST_Distance( s.location::geography, ST_SetSRID(ST_MakePoint(#{lng}, #{lat}), 4326)::geography ) / 1000.0 AS numeric ), 2)
NULL::numeric
AS distance_km FROM spots s
s.status = #{status} AND s.deleted_at IS NULL
AND s.theme = #{theme}
ORDER BY
ST_Distance( s.location::geography, ST_SetSRID(ST_MakePoint(#{lng}, #{lat}), 4326)::geography )
s.bookmark_count DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM spots s

    s.status = #{status}
    AND s.deleted_at IS NULL

        AND s.theme = #{theme}

/* 뷰포트 조회 동적쿼리 */
    SELECT s.id, s.latitude, s.longitude, s.user_id
    FROM spots s
    WHERE s.location && ST_MakeEnvelope(#{minLng}, #{minLat}, #{maxLng}, #{maxLat}, 4326)
        AND s.status = #{status}
        AND s.deleted_at IS NULL

            AND s.theme = #{theme}
